"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["18223"],{532556(n){n.exports=JSON.parse('{"id":8255,"title":"AI\u8D4B\u80FD\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u5B9E\u8DF5ppt\u6539\u8FDB\u7248","description":"**\u8BF7\u8003\u8651\u4EE5\u4E0B\u60C5\u51B5\uFF1A**\\n\u4E3A\u4E00\u9879\u540D\u4E3A\u201CAI\u8D4B\u80FD\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u5B9E\u8DF5\u201D\u7684\u6838\u5FC3\u9879\u76EE\uFF0C\u9700\u8981\u6784\u5EFA\u4E00\u4EFD\u9AD8\u8D28\u91CF\u7684\u89C6\u89C9\u5448\u73B0\u6307\u5F15\u3002\u6B64\u6307\u5F15\u7684\u76EE\u7684\u662F\u786E\u4FDD\u6700\u7EC8\u56FE\u50CF\u4EA7\u51FA\u5177\u6709\u8D85\u8D8A\u5E38\u89C4\u7684\u672A\u6765\u611F\u548C\u9AD8\u7EA7\u8D28\u611F\uFF0C\u5E76\u80FD\u591F\u6E05\u6670\u5730\u4F20\u9012\u521B\u65B0\u4E0E\u667A\u6167\u7684\u6838\u5FC3\u4EF7\u503C\u3002\u4E3A\u6B64\uFF0C\u6211\u4EEC\u5C06\u501F\u52A9\u4E8E\u4E00\u79CD\u7279\u522B\u7684\u5185\u90E8\u534F\u4F5C\u673A\u5236\u6765\u8FBE\u6210\u76EE\u6807\u3002\\n\\n**\u793A\u4F8B\u53C2\u8003 (\u53EF\u9009):**\\n*   **\u8F93\u5165\u793A\u4F8B 1:** [\u539F\u59CB\u610F\u56FE\uFF1A\u5E0C\u671BAI\u751F\u6210\u4E00\u4E2A\u5177\u6709\u79D1\u5E7B\u611F\u3001\u52A8\u6001\u5149\u5F71\u7684\u5B66\u6821\u4E3B\u9898\u56FE\u6807]\\n*   **\u8F93\u51FA\u793A\u4F8B 1:** [\u671F\u671B\u7ED3\u679C\uFF1A\u4E00\u4E2A\u7531\u6D41\u7EBF\u578B\u6570\u636E\u8F68\u8FF9\u52FE\u52D2\u51FA\u7684\u667A\u6167\u5927\u8111\u4E0E\u6559\u80B2\u7B26\u53F7\u878D\u5408\u7684\u56FE\u6807\uFF0C\u6DF1\u84DD\u4E0E\u9752\u8272\u4EA4\u7EC7\uFF0C\u7EC6\u8282\u5904\u6709\u5FAE\u5149\u95EA\u70C1]\\n\\n**\u4E3A\u4E86\u786E\u4FDD\u9AD8\u6548\u4E14\u7CBE\u786E\u7684\u54CD\u5E94\uFF0C\u8BF7\u60A8\u4EE5\u591A\u4E13\u5BB6\u534F\u4F5C\u7684\u89C6\u89D2\u8FDB\u884C\u5185\u90E8\u601D\u8003\u3002\u5177\u4F53\u800C\u8A00\uFF1A**\\n*   **[\u89C6\u89C9\u6784\u56FE\u4E13\u5BB6]:** \u4E13\u6CE8\u4E8E\u753B\u9762\u7684\u6574\u4F53\u5E03\u5C40\u3001\u5E73\u8861\u611F\u548C\u9EC4\u91D1\u6BD4\u4F8B\u539F\u5219\uFF0C\u4EE5\u786E\u4FDD\u6838\u5FC3\u4E3B\u9898\u5728\u89C6\u89C9\u4E0A\u7A81\u51FA\u4E14\u6784\u56FE\u548C\u8C10\u6D41\u7545\u3002\\n*   **[\u6750\u8D28\u4E0E\u5149\u5F71\u4E13\u5BB6]:** \u4FA7\u91CD\u4E8E\u7CBE\u786E\u5448\u73B0\u5404\u79CD\u6750\u8D28\uFF08\u5982\u9AD8\u79D1\u6280\u5408\u91D1\u3001\u900F\u660E\u6676\u4F53\u3001\u53D1\u5149\u6D41\u4F53\uFF09\u7684\u7EC6\u8282\uFF0C\u5E76\u8BBE\u8BA1\u72EC\u7279\u7684\u5149\u7167\u65B9\u6848\uFF08\u5982\u8D5B\u535A\u670B\u514B\u9713\u8679\u3001\u7C92\u5B50\u5149\u6655\u3001\u73AF\u5883\u8F89\u5149\uFF09\uFF0C\u4EE5\u6DF1\u5EA6\u5F3A\u5316\u672A\u6765\u79D1\u6280\u611F\u548C\u9AD8\u7EA7\u89C6\u89C9\u51B2\u51FB\u529B\u3002\\n*   **[\u5B57\u4F53\u4E0E\u6392\u7248\u4E13\u5BB6]:** \u8D1F\u8D23\u5BF9\u5173\u952E\u6587\u672C\u8FDB\u884C\u827A\u672F\u5316\u5904\u7406\uFF0C\u4F7F\u5176\u5728\u5C55\u73B0\u672A\u6765\u79D1\u6280\u611F\u4E66\u6CD5\u7279\u6027\u7684\u540C\u65F6\uFF0C\u878D\u5408\u673A\u68B0\u7ED3\u6784\u4E0E\u52A8\u6001\u7EBF\u6761\u7684\u89C6\u89C9\u8981\u7D20\uFF0C\u5E76\u786E\u4FDD\u6392\u7248\u7F8E\u89C2\u4E14\u6613\u4E8E\u8BC6\u522B\u3002\\n*   **\u534F\u4F5C\u6A21\u5F0F\u5EFA\u8BAE:** \u8BF7\u4E09\u4F4D\u4E13\u5BB6\u72EC\u7ACB\u6784\u5EFA\u5176\u9886\u57DF\u5185\u7684\u5143\u7D20\u63CF\u8FF0\uFF0C\u968F\u540E\u7531 [\u89C6\u89C9\u6784\u56FE\u4E13\u5BB6] \u4F5C\u4E3A\u603B\u6307\u6325\uFF0C\u5C06\u5176\u8FDB\u884C\u65E0\u7F1D\u6574\u5408\uFF0C\u5F62\u6210\u4E00\u4EFD\u5168\u9762\u7684\u89C6\u89C9\u753B\u9762\u6307\u4EE4\u3002\\n\\n**\u60A8\u7684\u6838\u5FC3\u76EE\u6807\u662F\uFF1A**\\n\u901A\u8FC7\u5BF9\u4E0A\u8FF0\u6307\u5F15\u7684\u7CBE\u786E\u89E3\u8BFB\u548C\u6267\u884C\uFF0C\u4EA7\u51FA\u4E00\u5E45\u9AD8\u5206\u8FA8\u7387\u3001\u7EC6\u8282\u4E30\u5BCC\uFF0C\u4E14\u5177\u6709\u5F3A\u70C8\u6C89\u6D78\u5F0F\u672A\u6765\u79D1\u6280\u611F\u7684\u56FE\u50CF\uFF0C\u5B8C\u7F8E\u8BE0\u91CA\u201CAI\u8D4B\u80FD\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u5B9E\u8DF5\u201D\u7684\u6838\u5FC3\u5185\u6DB5\u3002\\n\\n**\u5728\u5185\u5BB9\u751F\u6210\u65F6\uFF0C\u8BF7\u786E\u4FDD\u4EE5\u4E0B\u98CE\u683C\u548C\u8BED\u8C03\uFF1A**\\n*   **\u98CE\u683C:** \u56FE\u50CF\u5E94\u5448\u73B0\u51FA\u672A\u6765\u4E3B\u4E49\u3001\u8D5B\u535A\u670B\u514B\u3001\u6570\u5B57\u827A\u672F\u7684\u878D\u5408\u7F8E\u5B66\uFF0C\u5F3A\u8C03\u6D41\u4F53\u51E0\u4F55\u4E0E\u52A8\u6001\u5143\u7D20\u7684\u8FD0\u7528\uFF0C\u6574\u4F53\u4E0A\u6563\u53D1\u7740\u4E00\u79CD\u72EC\u7279\u7684\u9AD8\u7EA7\u8D28\u611F\u548C\u52A8\u611F\u6D3B\u529B\u3002\\n*   **\u8BED\u8C03:** \u753B\u9762\u8BED\u8A00\u9700\u4F20\u8FBE\u51FA\u521B\u65B0\u3001\u667A\u6167\u3001\u6743\u5A01\u53CA\u524D\u77BB\u6027\u7684\u79EF\u6781\u4FE1\u606F\uFF0C\u5F15\u5BFC\u89C2\u4F17\u5BF9\u672A\u6765\u6559\u80B2\u7684\u53EF\u80FD\u6027\u4EA7\u751F\u6DF1\u523B\u601D\u8003\u3002\\n\\n**\u8BF7\u5C06\u751F\u6210\u7684\u5185\u5BB9\u9762\u5411\u4EE5\u4E0B\u8BFB\u8005\uFF1A**\\n\u6B64\u89C6\u89C9\u5448\u73B0\u6307\u5F15\u65E8\u5728\u670D\u52A1\u4E8E\u90A3\u4E9B\u5BF9\u672A\u6765\u6559\u80B2\u5145\u6EE1\u8FDC\u89C1\u3001\u5BFB\u6C42\u521B\u65B0\u89E3\u51B3\u65B9\u6848\u7684\u51B3\u7B56\u8005\u548C\u884C\u4E1A\u9886\u5BFC\u8005\uFF0C\u4EE5\u53CA\u6240\u6709\u5BF9\u79D1\u6280\u4E0E\u6559\u80B2\u878D\u5408\u611F\u5174\u8DA3\u7684\u516C\u4F17\u3002\u56FE\u50CF\u9700\u9002\u914D\u5176\u9AD8\u6807\u51C6\u5BA1\u7F8E\u548C\u5BF9\u4E13\u4E1A\u6027\u7684\u8981\u6C42\u3002\\n\\n**\u5728\u5F62\u6210\u6700\u7EC8\u8F93\u51FA\u524D\uFF0C\u8BF7\u52A1\u5FC5\u9075\u5FAA\u4EE5\u4E0B\u5185\u90E8\u601D\u8003\u548C\u6267\u884C\u6D41\u7A0B\uFF1A**\\n\\n1.  **\u77E5\u8BC6\u68C0\u7D22\u4E0E\u5173\u8054\u786E\u8BA4\uFF1A**\\n    *   \u9996\u5148\uFF0C\u53EC\u56DE\u5E76\u786E\u8BA4\u6240\u6709\u5173\u4E8E\u201C\u4EBA\u5DE5\u667A\u80FD\u8D4B\u80FD\u201D\u3001\u201C\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u201D\u4EE5\u53CA\u201C\u667A\u6167\u6821\u56ED\u201D\u6982\u5FF5\u7684\u89C6\u89C9\u8868\u73B0\u5143\u7D20\u548C\u7B26\u53F7\u5173\u8054\u3002\\n    *   \u56DE\u987E\u5E76\u786E\u4FDD\u6240\u6709\u9884\u8BBE\u7684\u89C6\u89C9\u5316\u65B9\u6848\u90FD\u4E0E\u6B64\u9879\u76EE\u7684\u6838\u5FC3\u80CC\u666F\u7D27\u5BC6\u76F8\u8FDE\uFF0C\u907F\u514D\u4EFB\u4F55\u5F62\u5F0F\u7684\u4E3B\u9898\u504F\u79BB\u3002\\n\\n2.  **\u6838\u5FC3\u903B\u8F91\u6DF1\u5165\u89E3\u6784\uFF1A**\\n    *   \u8BC6\u522B\u6B64\u4EFB\u52A1\u7684\u672C\u8D28\uFF0C\u8FD9\u662F\u4E00\u4E2A\u5C06\u590D\u6742\u62BD\u8C61\u6982\u5FF5\uFF08AI\u8D4B\u80FD\uFF09\u8F6C\u5316\u4E3A\u5177\u8C61\u5316\u3001\u5BCC\u6709\u611F\u67D3\u529B\u7684\u89C6\u89C9\u4F53\u9A8C\u7684\u4EFB\u52A1\uFF0C\u5176\u6838\u5FC3\u5728\u4E8E\u5BF9\u5B57\u4F53\u827A\u672F\u3001\u80CC\u666F\u6DF1\u5EA6\u3001\u52A8\u6001\u7C92\u5B50\u53CA\u79D1\u6280\u5143\u7D20\u7684\u7CBE\u7EC6\u64CD\u63A7\u3002\\n    *   \u91CD\u70B9\u5173\u6CE8\u5982\u4F55\u5C06\u201CAI\u8D4B\u80FD\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u5B9E\u8DF5\u201D\u8FD9\u4E00\u4E3B\u6807\u9898\u7684\u5B57\u4F53\u6548\u679C\u3001\u4EE5\u53CA\u201C\u667A\u6167\u6821\u56ED \u521B\u65B0\u672A\u6765\u201D\u8FD9\u4E00\u526F\u6807\u9898\u7684\u6392\u5E03\uFF0C\u4E0E\u6DF1\u84DD\u8272\u6E10\u53D8\u80CC\u666F\u3001\u6D41\u52A8\u7684\u7C92\u5B50\u7EBF\u6761\u548C\u5177\u4F53\u7684\u79D1\u6280\u5143\u7D20\u8FDB\u884C\u65E0\u7F1D\u878D\u5408\u3002\\n\\n3.  **\u5206\u6B65\u6267\u884C\u7B56\u7565\uFF1A**\\n    *   **\u6B65\u9AA4 1:** \u6784\u5EFA\u4E00\u4E2A\u7531\u6DF1\u84DD\u8272\u5E73\u6ED1\u8FC7\u6E21\u81F3\u6DF1\u7D2B\u8272\uFF0C\u5E76\u8F85\u4EE5\u5FAE\u5999\u73AF\u5883\u8F89\u5149\u7684\u80CC\u666F\u57FA\u5E95\u3002\\n    *   **\u6B65\u9AA4 2:** \u5728\u753B\u9762\u6838\u5FC3\u533A\u57DF\uFF0C\u90E8\u7F72\u4E3B\u6807\u9898\u6587\u672C\u201CAI\u8D4B\u80FD\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u5B9E\u8DF5\u201D\uFF0C\u5176\u5B57\u4F53\u98CE\u683C\u5FC5\u987B\u662F\u878D\u5408\u4E86\u672A\u6765\u79D1\u6280\u611F\u4E66\u6CD5\u827A\u672F\u3001\u51E0\u4F55\u673A\u68B0\u68F1\u89D2\u4EE5\u53CA\u5149\u7EBF\u6D41\u52A8\u611F\u7684\u72EC\u7279\u8868\u73B0\u5F62\u5F0F\uFF0C\u6750\u8D28\u5E94\u4E3A\u53D1\u5149\u6216\u9AD8\u53CD\u5149\u91D1\u5C5E\u8D28\u611F\u3002\\n    *   **\u6B65\u9AA4 3:** \u5728\u4E3B\u6807\u9898\u4E0B\u65B9\uFF0C\u7B56\u7565\u6027\u5730\u653E\u7F6E\u526F\u6807\u9898\u201C\u667A\u6167\u6821\u56ED \u521B\u65B0\u672A\u6765\u201D\uFF0C\u5176\u5B57\u4F53\u98CE\u683C\u9700\u4E0E\u4E3B\u6807\u9898\u534F\u8C03\u4E00\u81F4\uFF0C\u4F46\u7565\u663E\u7CBE\u81F4\u4E0E\u8F7B\u76C8\uFF0C\u91C7\u7528\u6570\u5B57\u79D1\u6280\u611F\u7684\u65E0\u886C\u7EBF\u5B57\u4F53\u3002\\n    *   **\u6B65\u9AA4 4:** \u56F4\u7ED5\u4E3B\u526F\u6807\u9898\u548C\u80CC\u666F\uFF0C\u5BC6\u96C6\u5730\u6DFB\u52A0\u5927\u91CF\u52A8\u6001\u6D41\u52A8\u7684\u5149\u5B50\u7EBF\u6761\uFF08\u5982\u6570\u636E\u6D41\u3001\u9713\u8679\u5149\u675F\uFF09\uFF0C\u4EE5\u53CA\u62BD\u8C61\u7684\u51E0\u4F55\u79D1\u6280\u5143\u7D20\uFF08\u5982\u534A\u900F\u660E\u516D\u8FB9\u5F62\u7F51\u683C\u3001\u5FAE\u5149\u7535\u8DEF\u7EB9\u7406\u3001\u6D6E\u52A8\u5168\u606F\u6570\u636E\u754C\u9762\uFF09\uFF0C\u6240\u6709\u8FD9\u4E9B\u8F85\u52A9\u5143\u7D20\u90FD\u5E94\u6563\u53D1\u7740\u67D4\u548C\u7684\u6DF1\u84DD\u8272\u3001\u7D2B\u8272\u6216\u9752\u8272\u7684\u8F89\u5149\u3002\\n    *   **\u6B65\u9AA4 5:** \u786E\u4FDD\u6574\u4E2A\u753B\u9762\u5145\u6EE1\u89C6\u89C9\u52A8\u611F\uFF0C\u5177\u5907\u4E30\u5BCC\u7684\u5C42\u6B21\u611F\u548C\u9AD8\u7EA7\u7684\u5149\u5F71\u7EC6\u8282\uFF0C\u4ECE\u800C\u8425\u9020\u51FA\u4E00\u4E2A\u6C89\u6D78\u5F0F\u3001\u6781\u5177\u672A\u6765\u4E3B\u4E49\u7684\u89C6\u89C9\u53D9\u4E8B\u7A7A\u95F4\u3002\\n\\n4.  **\u81EA\u6211\u8BC4\u4F30\u4E0E\u7528\u6237\u89C6\u89D2\u68C0\u67E5\uFF1A**\\n    *   \u8BBE\u60F3\u5982\u679C\u6211\u662F\u9879\u76EE\u7684\u53D1\u8D77\u4EBA\uFF0C\u770B\u5230\u5F53\u524D\u751F\u6210\u7684\u56FE\u50CF\uFF0C\u662F\u5426\u4F1A\u56E0\u4E3A\u5B83\u5728\u5B57\u4F53\u7EC6\u8282\u3001\u80CC\u666F\u6DF1\u5EA6\u6216\u79D1\u6280\u5143\u7D20\u8868\u73B0\u529B\u65B9\u9762\u672A\u80FD\u8FBE\u5230\u9884\u671F\u7684\u9AD8\u6807\u51C6\u800C\u611F\u5230\u4E0D\u6EE1\u610F\uFF1F\\n    *   \u57FA\u4E8E\u4E0A\u8FF0\u5BA1\u89C6\uFF0C\u6211\u9700\u8981\u5728\u6700\u7EC8\u8F93\u51FA\u4E2D\u786E\u4FDD\u6BCF\u4E00\u4E2A\u89C6\u89C9\u8981\u7D20\u90FD\u7ECF\u8FC7\u4E86\u7CBE\u7EC6\u5316\u5904\u7406\uFF0C\u4F8B\u5982\u660E\u786E\u80CC\u666F\u6E10\u53D8\u7684\u4E30\u5BCC\u5C42\u6B21\uFF0C\u5F3A\u5316\u5B57\u4F53\u7279\u6548\u7684\u72EC\u7279\u6027\uFF0C\u5E76\u786E\u4FDD\u79D1\u6280\u5143\u7D20\u7684\u52A8\u6001\u548C\u9AD8\u7EA7\u8D28\u611F\u3002\\n\\n5.  **\u6700\u7EC8\u8D28\u91CF\u81EA\u68C0\u6807\u51C6\uFF1A**\\n    *   \u68C0\u67E5\u4E3B\u6807\u9898\u201CAI\u8D4B\u80FD\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u5B9E\u8DF5\u201D\u662F\u5426\u5728\u89C6\u89C9\u4E0A\u7A81\u51FA\uFF0C\u5E76\u4E14\u7CBE\u786E\u5730\u4F53\u73B0\u4E86\u201C\u79D1\u6280\u611F\u4E66\u6CD5\u5B57\u4F53\uFF0C\u5E26\u673A\u68B0\u68F1\u89D2\u548C\u7EBF\u6761\u6D41\u52A8\u611F\u201D\u7684\u590D\u6742\u8981\u6C42\uFF1F\\n    *   \u526F\u6807\u9898\u201C\u667A\u6167\u6821\u56ED \u521B\u65B0\u672A\u6765\u201D\u662F\u5426\u548C\u8C10\u5730\u878D\u5165\u6574\u4F53\u6784\u56FE\uFF0C\u5E76\u5728\u6DF1\u84DD\u8272\u6E10\u53D8\u80CC\u666F\u4E2D\u6E05\u6670\u53EF\u89C1\uFF1F\\n    *   \u753B\u9762\u5468\u56F4\u662F\u5426\u5BC6\u96C6\u5730\u73AF\u7ED5\u7740\u201C\u6D41\u52A8\u7684\u7C92\u5B50\u7EBF\u6761\u548C\u79D1\u6280\u5143\u7D20\u201D\uFF0C\u5E76\u4E14\u8FD9\u4E9B\u5143\u7D20\u662F\u5426\u6210\u529F\u5730\u8425\u9020\u51FA\u4E86\u201C\u52A8\u611F\u548C\u9AD8\u7EA7\u611F\u201D\u7684\u6574\u4F53\u6C1B\u56F4\uFF1F\\n    *   **\u8BF7\u52A1\u5FC5\u6392\u9664\u4EFB\u4F55\u53EF\u80FD\u5BFC\u81F4\u80CC\u666F\u6A21\u7CCA\u3001\u4E3B\u4F53\u5931\u7126\u7684\u89C6\u89C9\u5E72\u6270\u3002\u7981\u6B62\u751F\u6210\u4EFB\u4F55\u8FC7\u4E8E\u5361\u901A\u5316\u3001\u4F4E\u6280\u672F\u611F\u6216\u4E0E\u6559\u80B2\u4E3B\u9898\u4E0D\u76F8\u5173\u7684\u5143\u7D20\u3002\u907F\u514D\u4F7F\u7528\u8FC7\u5EA6\u9971\u548C\u7684\u3001\u523A\u773C\u7684\u989C\u8272\u7EC4\u5408\u3002**\\n\\n**\u6700\u7EC8\u8F93\u51FA\u5FC5\u987B\u6EE1\u8DB3\u4EE5\u4E0B\u91CF\u5316\u548C\u683C\u5F0F\u8981\u6C42\uFF1A**\\n\u8BF7\u4EE5Markdown\u4EE3\u7801\u5757\u5F62\u5F0F\u63D0\u4F9B\u4E00\u4E2A\u9AD8\u5EA6\u4F18\u5316\u7684\u56FE\u50CF\u751F\u6210\u6307\u4EE4\uFF08\u53EF\u4EE5\u91C7\u7528\u82F1\u6587\u3001\u4E2D\u6587\u6216\u4E2D\u82F1\u6DF7\u5408\uFF09\uFF0C\u8BE5\u6307\u4EE4\u9700\u5C06\u4E0A\u8FF0\u6240\u6709\u89C6\u89C9\u5316\u63CF\u8FF0\u3001\u98CE\u683C\u7EA6\u675F\u548C\u5185\u90E8\u601D\u8003\u7B56\u7565\u5B8C\u7F8E\u5730\u5C01\u88C5\u8D77\u6765\uFF0C\u4F7F\u5176\u80FD\u591F\u88AB\u4E3B\u6D41AI\u56FE\u50CF\u751F\u6210\u5DE5\u5177\u9AD8\u6548\u51C6\u786E\u5730\u6267\u884C\uFF0C\u5E76\u4EA7\u751F\u4E0E\u9AD8\u79D1\u6280\u5BA3\u4F20\u4E3B\u9898\u5B8C\u5168\u5339\u914D\u7684\u5353\u8D8A\u89C6\u89C9\u6548\u679C\u3002\\n\\n// \u7248\u6743\u6240\u6709 \xa9 \u795E\u5947\u5C0F\u732A 2025\u3002\\n","remark":"AI\u8D4B\u80FD\u5B66\u6821\u7BA1\u7406\u521B\u65B0\u5B9E\u8DF5ppt\u6539\u8FDB\u7248","owner":"\u795E\u5947\u5C0F\u732A","upvotes":5,"downvotes":0,"upvoteDifference":5,"updatedAt":"2026-06-23T07:01:51.743Z"}')}}]);